MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    base64_length;

  /* Validate input parameters */
  if ((image_info == (ImageInfo *) NULL) || (image == (Image *) NULL))
    return (MagickFalse);

  /* Log the filename if debugging is enabled */
  if (image_info->debug)
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Writing \"INLINE\" image format");

  /* Clone the image information */
  clone_image = CloneImage(image, 0, 0, MagickTrue, (ExceptionInfo *) NULL);
  if (clone_image == (Image *) NULL)
    return (MagickFalse);

  /* Check if the format is "INLINE" */
  if (LocaleCaseCompare(clone_image->magick, "INLINE") != 0)
    return (MagickFalse);

  /* Retrieve the corresponding MagickInfo */
  magick_info = GetMagickInfo(clone_image->magick, (ExceptionInfo *) NULL);
  if (magick_info == (MagickInfo *) NULL)
    return (MagickFalse);

  /* Convert the image to a blob */
  (void) SetImageColorspace(clone_image, sRGBColorspace);
  status = WriteBlobImage(clone_image, &base64_data, &base64_length);
  if (status == MagickFalse)
  {
    clone_image = DestroyImage(clone_image);
    return (MagickFalse);
  }

  /* Encode the blob data in Base64 */
  base64_data = (char *) Base64Encode((const unsigned char *) base64_data, base64_length);
  if (base64_data == (char *) NULL)
  {
    clone_image = DestroyImage(clone_image);
    return (MagickFalse);
  }

  /* Open a binary blob for writing */
  clone_image->blob = OpenBlob(clone_image, &clone_image->exception, WriteBinaryBlob, 0);
  if (clone_image->blob == (void *) NULL)
  {
    clone_image = DestroyImage(clone_image);
    return (MagickFalse);
  }

  /* Write the Base64-encoded data */
  status = WriteBlob(clone_image, (size_t) strlen(base64_data), (void *) base64_data);
  if (status == MagickFalse)
  {
    clone_image = DestroyImage(clone_image);
    return (MagickFalse);
  }

  /* Clean up resources */
  base64_data = (char *) RelinquishMemory(base64_data);
  clone_image = DestroyImage(clone_image);

  return (MagickTrue);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    base64_length;

  /* Validate input parameters */
  if ((image == (Image *) NULL) || (image->signature != MagickSignature))
    return(MagickFalse);

  if (image_info == (ImageInfo *) NULL)
    return(MagickFalse);

  if (GetImageFormat(image_info) != INLINE)
    return(MagickFalse);

  magick_info = GetMagickInfo("INLINE", NULL);
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  clone_image = CloneImage(image, image->columns, image->rows, MagickTrue, exception);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  status = ConvertImage(clone_image, &base64_data, &base64_length, "INLINE", exception);
  if (status == MagickFalse)
    goto cleanup;

  if (WriteBlobMemory(image, base64_length, base64_data) != MagickTrue)
    status = MagickFalse;

cleanup:
  if (clone_image != (Image *) NULL)
    DestroyImage(clone_image);
  if (base64_data != (char *) NULL)
    MagickFreeMemory(base64_data);
  return status;
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  register ssize_t
    i;

  StringInfo
    *blob;

  size_t
    length;

  char
    *base64,
    *p;

  if ((image_info == (ImageInfo *) NULL) || (image == (Image *) NULL))
    return (MagickFalse);

  if (GetMagickSetting(image_info,"filename:INLINE") != MagickFalse)
    {
      (void) LogMagickEvent(CoderEvent,GetMagickModule(),"filename: %s",
        image_info->filename);
      (void) CloneString(&image_info->magick,"INLINE");
    }

  magick_info=GetMagickInfo(image_info->magick,image_info->options);
  if (magick_info == (MagickInfo *) NULL)
    return (MagickFalse);

  clone_image=CloneImage(image,0,0,MagickTrue,NULL);
  if (clone_image == (Image *) NULL)
    return (MagickFalse);

  status=BlobImage(clone_image,image_info,NULL);
  if (status == MagickFalse)
    {
      InheritException(image,clone_image->exception);
      DestroyBlob(clone_image);
      (void) DeleteImageFromList(&clone_image);
      return (MagickFalse);
    }

  length=GetBlobSize(clone_image);
  if (length == 0)
    {
      (void) DeleteImageFromList(&clone_image);
      return (MagickTrue);
    }

  base64=(char *) AcquireMemory((4U*(length/3U)+4U)*sizeof(*base64));
  if (base64 == (char *) NULL)
    {
      (void) DeleteImageFromList(&clone_image);
      return (MagickFalse);
    }

  p=base64;
  for (i=0; i < (ssize_t) length; i+=3)
  {
    switch (length-i)
    {
      case 1:
      {
        *p++=IndexToBase64Byte[(GetBlobByte(clone_image,i) >> 2) & 0x3F];
        *p++=IndexToBase64Byte[(GetBlobByte(clone_image,i) << 4) & 0x30];
        *p++='=';
        *p++='=';
        break;
      }
      case 2:
      {
        *p++=IndexToBase64Byte[(GetBlobByte(clone_image,i) >> 2) & 0x3F];
        *p++=IndexToBase64Byte[((GetBlobByte(clone_image,i) << 4) & 0x30) |
          (GetBlobByte(clone_image,i+1) >> 4)];
        *p++=IndexToBase64Byte[(GetBlobByte(clone_image,i+1) << 2) & 0x3C];
        *p++='=';
        break;
      }
      default:
      {
        *p++=IndexToBase64Byte[(GetBlobByte(clone_image,i) >> 2) & 0x3F];
        *p++=IndexToBase64Byte[((GetBlobByte(clone_image,i) << 4) & 0x30) |
          (GetBlobByte(clone_image,i+1) >> 4)];
        *p++=IndexToBase64Byte[((GetBlobByte(clone_image,i+1) << 2) & 0x3C) |
          (GetBlobByte(clone_image,i+2) >> 6)];
        *p++=IndexToBase64Byte[GetBlobByte(clone_image,i+2) & 0x3F];
        break;
      }
    }
  }

  blob=BlobString(base64,strlen(base64));
  if (blob == (StringInfo *) NULL)
    {
      RelinquishMemory(base64);
      (void) DeleteImageFromList(&clone_image);
      return (MagickFalse);
    }

  (void) CopyString(base64,"data:image/");
  (void) ConcatenateString(&base64,clone_image->magick);
  (void) ConcatenateString(&base64,";base64,");
  (void) ConcatenateString(&base64,(char *) GetStringFromBlob(blob));

  status=OpenBlob(image_info,blob,WriteBinaryBlob,clone_image);
  if (status != MagickFalse)
    {
      (void) WriteBlob(clone_image,strlen(base64),base64);
      (void) CloseBlob(clone_image);
    }

  RelinquishMemory(base64);
  DestroyBlob(clone_image);
  DestroyBlob(blob);
  (void) DeleteImageFromList(&clone_image);
  return (status);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image) {
  MagickBooleanType
    status;

  Image
    *clone_image;

  MagickInfo
    *magick_info;

  register ssize_t
    i;

  size_t
    length;

  StringInfo
    *blob;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  (void) LogMagickEvent(TraceEvent, GetMagickModule(), "Enter WriteINLINEImage()");

  if (LocaleCaseCompare(image_info->format,"INLINE") != 0)
    return(MagickFalse);

  magick_info=GetMagickInfo("INLINE",image_info->options);
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  clone_image=CloneImage(image,0,0,MagickTrue,&image->exception);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  (void) CloneImageProfiles(clone_image,image);
  (void) SetImageColorspace(clone_image,sRGBColorspace);

  blob=BlobToStringInfo((void *) NULL,0);
  if (blob == (StringInfo *) NULL)
    {
      clone_image=DestroyImage(clone_image);
      return(MagickFalse);
    }

  status=WriteImages(clone_image,blob,MagickTrue,&image->exception);
  clone_image=DestroyImage(clone_image);
  if (status == MagickFalse)
    {
      blob=DestroyStringInfo(blob);
      return(MagickFalse);
    }

  length=GetStringInfoLength(blob);
  if (length == 0)
    {
      blob=DestroyStringInfo(blob);
      return(MagickFalse);
    }

  blob=Base64Encode(blob,length);
  if (blob == (StringInfo *) NULL)
    {
      blob=DestroyStringInfo(blob);
      return(MagickFalse);
    }

  (void) SetImageBlob(image,blob);

  (void) LogMagickEvent(TraceEvent,GetMagickModule(),"Leave WriteINLINEImage()");
  return(MagickTrue);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType status;
  Image
    *clone_image;

  MagickInfo
    *magick_info;

  StringInfo
    *blob;

  size_t
    length;

  char
    *base64_data;

  clone_image = CloneImage(image, 0, 0, MagickTrue, NULL);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  if (SetImageFormat(clone_image, "INLINE") != MagickTrue)
  {
    InheritException(clone_image, &clone_image->exception);
    return(MagickFalse);
  }

  magick_info = GetMagickInfo(clone_image->magick, clone_image->exception);
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  if (magick_info->decoder == (DecodeImageHandler *) NULL)
  {
    ThrowBinaryException(ImageError,"NoDecodeDelegate","INLINE");
    return(MagickFalse);
  }

  blob = CloneStringInfo(clone_image->blob);
  if (blob == (StringInfo *) NULL)
    return(MagickFalse);

  length = GetStringInfoLength(blob);
  base64_data = (char *) AcquireMemory(4 * length / 3 + 4);
  if (base64_data == (char *) NULL)
  {
    RelinquishMagickResource(blob);
    return(MagickFalse);
  }

  (void) base64_encode((const unsigned char *) GetStringInfoDatum(blob), length, base64_data);

  status = WriteBlobImage(image_info, clone_image, base64_data, length);

  RelinquishMagickResource(blob);
  base64_data = (char *) RelinquishMagickResource(base64_data);

  return(status);
}
